-- 17A POSTCHECKS P1 state PRE: one read-only statement; ok must be true on every row
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Read-only (a single SELECT over the catalog; the scan in P3c reads counts only).
WITH a(name, actual) AS (
  SELECT 'req.is_admin_exists' AS name, coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.profile_owners_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.rls_objects_enabled' AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'req.foldername_exists' AS name, coalesce((to_regprocedure('storage.foldername(text)') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_bucketless_anon_select' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (p.roles && ARRAY['public','anon']::name[]) AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) !~ 'bucket_id'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:agent-posts' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'agent-posts'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:chat-images' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:playlist-covers' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'playlist-covers'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:vs-entries' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.agent-posts' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-posts'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.chat-images' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.playlist-covers' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'playlist-covers'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.agent_posts_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_public_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.agent_posts_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_public_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images public read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist covers are publicly readable'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images public read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist covers are publicly readable'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_auth_upload.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images auth upload'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.rls_objects_enabled', 'true/false', ARRAY['true/false']::text[]),
  ('req.foldername_exists', 'true', ARRAY['true']::text[]),
  ('req.no_bucketless_anon_select', '0', ARRAY['0']::text[]),
  ('req.bucket_public:agent-posts', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:chat-images', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:playlist-covers', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:vs-entries', 'true', ARRAY['true']::text[]),
  ('sel.agent-posts', 'agent_posts_public_read', ARRAY['agent_posts_public_read']::text[]),
  ('sel.chat-images', 'chat images public read', ARRAY['chat images public read']::text[]),
  ('sel.playlist-covers', 'playlist covers are publicly readable', ARRAY['playlist covers are publicly readable']::text[]),
  ('sel.vs-entries', 'vs_media_read', ARRAY['vs_media_read']::text[]),
  ('pol.agent_posts_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.agent_posts_public_read.norm', 'bucket_id=''agent-posts''~', ARRAY['bucket_id=''agent-posts''~']::text[]),
  ('pol.chat_images_public_read.norm', 'bucket_id=''chat-images''~', ARRAY['bucket_id=''chat-images''~']::text[]),
  ('pol.playlist_public_read.norm', 'bucket_id=''playlist-covers''~', ARRAY['bucket_id=''playlist-covers''~']::text[]),
  ('pol.vs_media_read.norm', 'bucket_id=''vs-entries''~', ARRAY['bucket_id=''vs-entries''~']::text[]),
  ('pol.chat_images_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.playlist_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.vs_media_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.chat_images_auth_upload.shape', 'INSERT|authenticated|PERMISSIVE', ARRAY['INSERT|authenticated|PERMISSIVE']::text[]),
  ('ins.vs-entries', 'vs_media_insert', ARRAY['vs_media_insert']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'PRE' AS expected, 'PRE' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
